// LockMode.java — the lock modes
package com.nbi.db;

public enum LockMode {
    S,   // Shared  (read) — many allowed
    X,   // Exclusive (write) — only one
    IS,  // Intent Shared — intend to take S on a child row
    IX   // Intent Exclusive — intend to take X on a child row
}
