// LockManager.java — compatibility checks + escalation threshold
package com.nbi.db;

public class LockManager {

    // Lock compatibility matrix (true = can coexist).
    public boolean compatible(LockMode held, LockMode requested) {
        switch (held) {
            case S:  return requested == LockMode.S || requested == LockMode.IS;
            case X:  return false;                              // X conflicts with all
            case IS: return requested != LockMode.X;            // IS allows S/IS/IX
            case IX: return requested == LockMode.IS || requested == LockMode.IX;
            default: return false;
        }
    }

    // Escalation: once row locks exceed threshold, convert to one table lock.
    private static final int ESCALATION_THRESHOLD = 5000;
    public String maybeEscalate(int rowLocksHeld) {
        if (rowLocksHeld >= ESCALATION_THRESHOLD) {
            return "ESCALATED: " + rowLocksHeld
                    + " row locks -> 1 TABLE lock (low overhead, blocks whole table)";
        }
        return "row-level locking: " + rowLocksHeld + " row locks (high concurrency)";
    }
}
