// Demo.java — demonstrates S/X/intent compatibility and escalation vs batching
package com.nbi.db;

public class Demo {
    public static void main(String[] args) {
        LockManager lm = new LockManager();

        System.out.println("-- Lock compatibility --");
        System.out.println("  S  held, S  requested (two readers)      = " + lm.compatible(LockMode.S, LockMode.S));
        System.out.println("  S  held, X  requested (reader vs writer) = " + lm.compatible(LockMode.S, LockMode.X));
        System.out.println("  X  held, S  requested (writer blocks all)= " + lm.compatible(LockMode.X, LockMode.S));
        System.out.println("  IX held, IX requested (two row-writers)  = " + lm.compatible(LockMode.IX, LockMode.IX));
        System.out.println("  IX held, X  requested (table-lock wants) = " + lm.compatible(LockMode.IX, LockMode.X)
                + "   <- intent lock makes this conflict cheap to detect");

        System.out.println("\n-- Lock escalation --");
        System.out.println("  one huge UPDATE (3,000,000 rows): " + lm.maybeEscalate(3_000_000));
        System.out.println("  batched UPDATE (2,000 rows/chunk): " + lm.maybeEscalate(2_000)
                + "  <- stays below threshold, no escalation");
    }
}
